alter table public.tienda enable trigger tienda_publicar_legales;

-- Restablecer de fábrica con modo. La versión sin parámetros (0036) se borra:
-- una llamada sin modo usa 'completa'.
drop function if exists public.restablecer_fabrica();
create or replace function public.restablecer_fabrica(modo text default 'completa')
returns void
language plpgsql security definer set search_path = public
as $$
declare
  f jsonb := public.datos_fabrica();
  base public.tienda;
  datos_tienda jsonb;
begin
  if not public.es_administrador() then
    raise exception 'Solo el administrador puede restablecer el cotizador de fábrica.' using errcode = '42501';
  end if;
  if modo is null or modo not in ('completa', 'basica') then
    raise exception 'Algún dato no tiene el formato correcto. Revise los campos.' using errcode = '22023';
  end if;
  -- Desde aquí trabaja el sistema, como al instalar: los disparadores que
  -- protegen el catálogo del panel (colores_proteger, modelos_proteger) miran
  -- auth.uid(). Vale solo hasta el final de esta transacción.
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', '', true);

  delete from public.resenas;
  delete from public.equipos;
  -- Con sus fichas y colores (on delete cascade).
  delete from public.modelos;

  -- La tienda: los valores iniciales de cada columna, con los de fábrica
  -- encima (en el modo básico, sin los de la vitrina: quedan los iniciales).
  datos_tienda := f -> 'tienda';
  if modo = 'basica' then
    datos_tienda := datos_tienda - array(select jsonb_array_elements_text(f -> 'basica' -> 'tienda_sin'));
  end if;
  delete from public.tienda;
  insert into public.tienda (id) values (1) returning * into base;
  delete from public.tienda;
  insert into public.tienda select (jsonb_populate_record(base, datos_tienda)).*;

  insert into public.modelos
  select (jsonb_populate_record(null::public.modelos, jsonb_build_object('creado_en', now()) || m)).*
  from jsonb_array_elements(f -> 'modelos') m;
  -- modelos_ficha creó una ficha vacía por modelo: se llena con la de fábrica.
  update public.fichas x set descripcion = y.descripcion, especificaciones = y.especificaciones
  from jsonb_to_recordset(f -> 'fichas') as y (modelo_id bigint, descripcion text, especificaciones jsonb)
  where x.modelo_id = y.modelo_id;
  insert into public.colores
  select (jsonb_populate_record(null::public.colores, c)).*
  from jsonb_array_elements(f -> 'colores') c;

  -- Los equipos de demostración (marcan otra vez la fecha de los precios).
  if modo = 'completa' then
    insert into public.equipos
    select (jsonb_populate_record(null::public.equipos,
             jsonb_build_object('id', gen_random_uuid(), 'creado_en', now(), 'actualizado_en', now()) || e)).*
    from jsonb_array_elements(f -> 'equipos') e;
  else
    -- Los modelos que activó la vitrina se apagan; se activan los de estos equipos.
    update public.modelos set activo = false, activo_por_demo = false where activo_por_demo;
    insert into public.equipos (modelo_id, condicion, capacidad, color_id, color_nombre_mostrar, precio, en_stock,
      destacado, bateria_porcentaje, estado_estetico, detalles, incluye, publicado, es_demo)
    select m.id, e.condicion, e.capacidad, c.id, e.color_nombre_mostrar, e.precio, e.en_stock,
      e.destacado, e.bateria_porcentaje, e.estado_estetico, coalesce(e.detalles, ''), coalesce(e.incluye, ''), true, true
    from jsonb_to_recordset(f -> 'basica' -> 'equipos')
      as e (slug text, color text, capacidad text, condicion text, color_nombre_mostrar text, precio bigint, en_stock boolean,
            destacado boolean, bateria_porcentaje smallint, estado_estetico text, detalles text, incluye text)
    join public.modelos m on m.slug = e.slug
    join public.colores c on c.modelo_id = m.id and c.oficial and c.nombre_es = e.color;
    update public.modelos set activo = true, activo_por_demo = true
    where not activo and id in (select modelo_id from public.equipos where es_demo);
  end if;

  -- Los ids vuelven a ser los de fábrica: las secuencias siguen desde el mayor.
  perform setval('public.modelos_id_seq', greatest((select max(id) from public.modelos), (select last_value from public.modelos_id_seq)));
  perform setval('public.colores_id_seq', greatest((select max(id) from public.colores), (select last_value from public.colores_id_seq)));
end $$;

revoke execute on function public.restablecer_fabrica(text) from public, anon;
grant execute on function public.restablecer_fabrica(text) to authenticated;


